<script lang="ts">
    import { Switch } from '@skeletonlabs/skeleton-svelte';
    import Page from '../components/Page.svelte';
    import Field from '../components/Field.svelte';
    import Notice from '../components/Notice.svelte';
    import Strength from '../components/Strength.svelte';
    import Feature from '../components/Feature.svelte';
    import Setting from '../components/Setting.svelte';
    import DataTable from '../components/DataTable.svelte';
    import AdminPage from '../components/AdminPage.svelte';
    import { provideI18n } from '../lib/i18n';
    type Data = Record<string, any>;
    type I18n = { locale: string; messages: Record<string, string|string[]> };
    type Boot = { page: string; props: Data; themes: Data[]; theme: Data; debug: boolean; i18n?: I18n };
    type CredentialField = { input: string; label: string; required: boolean; secret: boolean; default?: string; type?: string };
    type ProviderDefinition = { label: string; user_managed: boolean; credentials: Record<string, CredentialField> };
    type PermissionDefinition = { id: string; label: string; description?: string|null; scopeKinds: string[] };
    type ActionGroup = { id: string; label: string; description?: string|null; permissionIds: string[] };
    let { boot }: { boot: Boot } = $props();
    provideI18n(() => boot.i18n?.messages ?? {});
    const p = $derived(boot.props), user = $derived(p.user ?? p.currentUser ?? null), csrf = $derived(p.csrfToken ?? '');
    let dark = $state(document.documentElement.classList.contains('dark'));
    let menu = $state(false), filter = $state(''), score = $state<number|null>(null), passkeyError = $state(''), busy = $state(false), keyName = $state('');
    const list = <T=Data>(v: T[]|null|undefined): T[] => v ?? [];
    const enc = (v: unknown) => encodeURIComponent(String(v ?? ''));
    const permission = (v: string) => list(user?.roles).some(r => list<string>(r.permissions).includes(v));
    const recordType = (r: Data) => typeof r.type === 'string' ? r.type : r.type?.value ?? '';
    const providerDefinitions = (v: unknown): [string, ProviderDefinition][] => Object.entries((v ?? {}) as Record<string, ProviderDefinition>);
    const credentialFields = (v: ProviderDefinition): CredentialField[] => Object.values(v.credentials ?? {});
    const permissionDefinitions = $derived(list<PermissionDefinition>(p.permissionDefinitions));
    const actionGroups = $derived(list<ActionGroup>(p.actionGroups));
    const groupedPermissionIds = $derived(new Set(actionGroups.flatMap(group => group.permissionIds)));
    const ungroupedPermissions = $derived(permissionDefinitions.filter(definition => !groupedPermissionIds.has(definition.id)));
    const interpolate = (text: string, parameters: Record<string, string|number> = {}) => text.replace(/\{([a-zA-Z0-9_]+)\}/g, (_, key) => String(parameters[key] ?? `{${key}}`));
    const t = (key: string, parameters: Record<string, string|number> = {}) => { const message = boot.i18n?.messages[key]; return interpolate(Array.isArray(message) ? message[0] : message ?? key, parameters); };
    const tp = (key: string, count: number, parameters: Record<string, string|number> = {}) => { const message = boot.i18n?.messages[key]; const template = Array.isArray(message) ? message[count === 1 ? 0 : 1] : message ?? key; return interpolate(template, { ...parameters, count }); };
    const permissionLabel = (permissionId: string) => t(permissionDefinitions.find(definition => definition.id === permissionId)?.label ?? permissionId);
    const actionGroupLabel = (group: ActionGroup) => t(group.label);
    const dateLabel = (value: string|null|undefined) => value ? new Intl.DateTimeFormat(user?.locale ?? boot.i18n?.locale ?? 'en-GB', { dateStyle: 'medium', timeStyle: 'short', timeZone: user?.timezone ?? 'UTC' }).format(new Date(value.replace(' ', 'T'))) : t('profile.never');
    const ask = (e: Event, text: string) => { if (!confirm(text)) e.preventDefault(); };
    const strength = (e: Event) => { const value=(e.currentTarget as HTMLInputElement).value; void import('zxcvbn').then(({default:zxcvbn})=>score=zxcvbn(value).score); };
    function setDark(v: boolean) { dark=v; document.documentElement.classList.toggle('dark',v); localStorage.setItem('towerdns-color-mode',v?'dark':'light'); }
    const toBuf=(s:string)=>{const b=s.replace(/-/g,'+').replace(/_/g,'/');return Uint8Array.from(atob(b+'='.repeat((4-b.length%4)%4)),c=>c.charCodeAt(0)).buffer};
    const toB64=(b:ArrayBuffer)=>btoa(String.fromCharCode(...new Uint8Array(b))).replace(/\+/g,'-').replace(/\//g,'_').replace(/=/g,'');
    async function loginPasskey(){busy=true;passkeyError='';try{const o=JSON.parse(p.optionsJson);o.challenge=toBuf(o.challenge);o.allowCredentials=list(o.allowCredentials).map(c=>({...c,id:toBuf(c.id)}));const a=await navigator.credentials.get({publicKey:o}) as PublicKeyCredential|null;if(!a)throw Error(t('passkey.error.no-authenticator-response'));const r=a.response as AuthenticatorAssertionResponse;const res=await fetch('/login/webauthn/finish',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id:toB64(a.rawId),rawId:toB64(a.rawId),type:a.type,response:{clientDataJSON:toB64(r.clientDataJSON),authenticatorData:toB64(r.authenticatorData),signature:toB64(r.signature),userHandle:r.userHandle?toB64(r.userHandle):null}})});const d=await res.json();if(!res.ok)throw Error(d.error??t('auth.error.login-failed'));location.href=d.redirect??'/';}catch(e){passkeyError=e instanceof Error?e.message:t('auth.error.login-failed');busy=false;}}
    async function registerPasskey(){if(!keyName.trim()){passkeyError=t('passkey.error.name-required');return}busy=true;passkeyError='';try{const begin=await fetch('/profile/webauthn/register/begin',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:`name=${enc(keyName)}&csrf_token=${enc(csrf)}`});const o=await begin.json();if(!begin.ok)throw Error(o.error??t('passkey.error.start-failed'));o.challenge=toBuf(o.challenge);o.user={...o.user,id:toBuf(o.user.id)};o.excludeCredentials=list(o.excludeCredentials).map(c=>({...c,id:toBuf(c.id)}));const c=await navigator.credentials.create({publicKey:o}) as PublicKeyCredential|null;if(!c)throw Error(t('passkey.error.no-authenticator-response'));const r=c.response as AuthenticatorAttestationResponse;const done=await fetch('/profile/webauthn/register/finish',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id:toB64(c.rawId),rawId:toB64(c.rawId),type:c.type,response:{clientDataJSON:toB64(r.clientDataJSON),attestationObject:toB64(r.attestationObject)}})});const d=await done.json();if(!done.ok)throw Error(d.error??t('passkey.error.registration-failed'));location.reload();}catch(e){passkeyError=e instanceof Error?e.message:t('passkey.error.registration-failed');busy=false;}}
</script>

<a class="skip-link" href="#main-content">{t('navigation.skip-to-content')}</a>
{#if user}<nav class="navbar"><div class="navbar-brand"><a class="navbar-item brand" href="/">TowerDNS</a><button class="navbar-burger" aria-label={t('navigation.menu')} onclick={()=>menu=!menu}><span></span><span></span><span></span></button></div><div class:open={menu} class="navbar-menu"><div class="navbar-start"><a class="navbar-item" href="/zones">{t('navigation.zones')}</a><a class="navbar-item" href="/accounts">{t('navigation.accounts')}</a>{#if permission('user.manage')}<a class="navbar-item" href="/users">{t('navigation.users')}</a>{/if}{#if permission('role.manage')}<a class="navbar-item" href="/roles">{t('navigation.roles')}</a>{/if}{#if permission('system.settings.manage')}<a class="navbar-item" href="/settings">{t('navigation.settings')}</a>{/if}{#if permission('provider.config.manage')}<a class="navbar-item" href="/credentials">{t('navigation.providers')}</a>{/if}</div><div class="navbar-end"><div class="navbar-item"><Switch checked={dark} onCheckedChange={(d)=>setDark(d.checked)} class="theme-switch" label={t('theme.label')}><Switch.Label>{dark?t('theme.dark'):t('theme.light')}</Switch.Label><Switch.Control class="theme-switch__control preset-filled-primary-500"><Switch.Thumb class="theme-switch__thumb">{dark?'☾':'☀'}</Switch.Thumb></Switch.Control><Switch.HiddenInput/></Switch></div><a class="navbar-item" href="/profile">{user.displayName||user.email}</a><form class="navbar-item" method="post" action="/logout"><input type="hidden" name="csrf_token" value={csrf}><button class="button is-small">{t('auth.logout')}</button></form></div></div></nav>{/if}

<main class:auth-page={!user} id="main-content">
{#if boot.debug}<Notice kind="warning" text={t('notice.debug-enabled')}/>{/if}
{#if ['login','forgot_password','reset_password','mfa_totp'].includes(boot.page)}
 <section class="auth-card box"><a class="wordmark" href="/">TowerDNS</a><h1 class="title is-4">{boot.page==='login'?t('auth.welcome-back'):boot.page==='forgot_password'?t('auth.forgot-password'):boot.page==='reset_password'?t('auth.new-password'):t('auth.two-factor')}</h1>{#if p.error}<Notice kind="danger" text={p.error}/>{/if}{#if p.sent}<Notice kind="success" text={t('auth.reset-email-sent')}/>{:else}<form method="post" action={boot.page==='login'?'/login':boot.page==='forgot_password'?'/password/forgot':boot.page==='reset_password'?'/password/reset':'/login/totp'}><input type="hidden" name="csrf_token" value={csrf}>{#if p.token}<input type="hidden" name="token" value={p.token}>{/if}{#if ['login','forgot_password'].includes(boot.page)}<Field label={t('field.email')}><input class="input" name="email" type="email" autocomplete="email" required></Field>{/if}{#if boot.page==='login'}<Field label={t('field.password')}><input class="input" name="password" type="password" autocomplete="current-password" required></Field>{/if}{#if boot.page==='reset_password'}<Field label={t('field.new-password')}><input class="input" name="password" type="password" oninput={strength} required><Strength value={score}/></Field><Field label={t('field.repeat')}><input class="input" name="password_confirm" type="password" required></Field>{/if}{#if boot.page==='mfa_totp'}<Field label={t('field.authenticator-code')}><input class="input code-input" name="code" inputmode="numeric" pattern={'[0-9]{6,8}'} required></Field>{/if}<button class="button is-primary is-fullwidth">{boot.page==='login'?t('auth.login'):boot.page==='forgot_password'?t('auth.send-reset-link'):boot.page==='reset_password'?t('common.save'):t('common.confirm')}</button></form>{/if}<div class="auth-links"><a href={boot.page==='login'?'/password/forgot':'/login'}>{boot.page==='login'?t('auth.forgot-password-question'):t('auth.back-to-login')}</a></div></section>
{:else if boot.page==='login_webauthn'}<section class="auth-card box"><a class="wordmark" href="/">TowerDNS</a><h1 class="title is-4">{t('auth.login-with-passkey')}</h1>{#if p.error||passkeyError}<Notice kind="danger" text={p.error||passkeyError}/>{/if}<button class:loading={busy} class="button is-primary is-fullwidth" onclick={loginPasskey}>{t('auth.use-passkey')}</button><div class="auth-links"><a href="/login">{t('auth.other-login-method')}</a></div></section>
{:else if boot.page==='dashboard'}<Page title={t('page.dashboard.title')} subtitle={t('dashboard.welcome',{name:user.displayName||user.email})}><div class="dashboard-grid"><Feature title={t('dashboard.zones.title')} text={t('dashboard.zones.text')} href="/zones"/><Feature title={t('dashboard.accounts.title')} text={t('dashboard.accounts.text')} href="/accounts"/><Feature title={t('dashboard.security.title')} text={t('dashboard.security.text')} href="/profile"/></div></Page>
{:else if boot.page==='zones/list'}<Page title={t('page.zones.title')} error={p.error}><section class="box"><form class="inline-form" method="post" action={`/accounts/${enc(p.accountId)}/zones`}><input type="hidden" name="csrf_token" value={csrf}><select class="input" name="provider_account_id" required>{#each list(p.providerAccounts) as provider}<option value={provider.id}>{provider.name}</option>{/each}</select><input class="input" name="zone_name" placeholder="example.com" required><button class="button is-primary">{t('zones.create')}</button></form><div class="resource-grid">{#each list(p.managedZones) as zone}<article class="resource-card"><div><a class="resource-title" href={`/accounts/${enc(p.accountId)}/zones/${enc(zone.id)}`}>{zone.canonicalName}</a><span class="status">{zone.providerAccountId}</span></div><form method="post" action={`/accounts/${enc(p.accountId)}/zones/${enc(zone.id)}/delete`} onsubmit={(e)=>ask(e,t('zones.confirm-delete',{name:zone.canonicalName}))}><input type="hidden" name="csrf_token" value={csrf}><button class="button is-small is-danger">{t('common.delete')}</button></form></article>{:else}<p class="empty">{t('zones.empty')}</p>{/each}</div></section></Page>
{:else if boot.page==='zones/records'}<Page title={p.managedZoneId} error={p.error} success={p.success}><div class="page-actions"><a class="button" href={`/accounts/${enc(p.accountId)}/zones`}>← {t('navigation.zones')}</a><a class="button" href={`/accounts/${enc(p.accountId)}/zones/${enc(p.managedZoneId)}/dnssec`}>DNSSEC</a></div><section class="box"><h2 class="subtitle">{t('rrset.save')}</h2><form method="post" action={`/accounts/${enc(p.accountId)}/zones/${enc(p.managedZoneId)}/rrsets`}><input type="hidden" name="csrf_token" value={csrf}><div class="form-grid"><Field label={t('field.name')}><input class="input" name="name" value="@" required></Field><Field label={t('field.type')}><input class="input" name="type" required></Field><Field label="TTL"><input class="input" name="ttl" type="number" value="300" required></Field></div><Field label="RDATA"><textarea class="input" name="rdata" rows="4" required></textarea></Field><button class="button is-primary">{t('rrset.save')}</button></form></section><table class="table"><tbody>{#each list(p.rrsets) as r}<tr><td><code>{r.ownerName}</code></td><td>{r.type?.presentation??r.type}</td><td>{r.ttl}</td><td class="actions"><form method="post" action={`/accounts/${enc(p.accountId)}/zones/${enc(p.managedZoneId)}/rrsets/${enc(r.ownerName)}/${enc(r.type?.presentation??r.type)}/delete`}><input type="hidden" name="csrf_token" value={csrf}><button class="button is-small is-danger">{t('rrset.delete')}</button></form></td></tr>{/each}</tbody></table></Page>
{:else if boot.page==='profile/index'}
<Page title={t('page.profile.title')} error={p.error} success={p.success} narrow>
 <section class="box"><h2 class="subtitle">{t('profile.identity.title')}</h2><form method="post" action="/profile"><input type="hidden" name="csrf_token" value={csrf}><div class="form-grid"><Field label={t('field.display-name')}><input class="input" name="display_name" value={user.displayName??''} maxlength="64"></Field><Field label={t('profile.first-name')}><input class="input" name="first_name" value={user.firstName??''} maxlength="100"></Field><Field label={t('profile.last-name')}><input class="input" name="last_name" value={user.lastName??''} maxlength="100"></Field><Field label={t('profile.alternate-email')}><input class="input" type="email" name="alternate_email" value={user.alternateEmail??''}></Field><Field label={t('profile.phone')}><input class="input" name="phone" value={user.phone??''}></Field><Field label={t('profile.mobile')}><input class="input" name="mobile" value={user.mobile??''}></Field><Field label={t('profile.street')}><input class="input" name="street" value={user.street??''}></Field><Field label={t('profile.street2')}><input class="input" name="street2" value={user.street2??''}></Field><Field label={t('profile.postal-code')}><input class="input" name="postal_code" value={user.postalCode??''}></Field><Field label={t('profile.city')}><input class="input" name="city" value={user.city??''}></Field><Field label={t('profile.region')}><input class="input" name="region" value={user.region??''}></Field><Field label={t('profile.country')}><input class="input" name="country" value={user.country??''} maxlength="2"></Field></div><Field label={t('profile.language')}><select class="input" name="language">{#each list<string>(p.supportedLanguages) as language}<option value={language} selected={user.language===language}>{t(`profile.locale.${language}`)}</option>{/each}</select></Field><Field label={t('profile.locale')}><select class="input" name="locale">{#each list<string>(p.supportedLocales) as locale}<option value={locale} selected={user.locale===locale}>{t(`profile.locale.${locale}`)}</option>{/each}</select></Field><Field label={t('profile.timezone')}><select class="input" name="timezone">{#each list<string>(p.supportedTimezones) as timezone}<option value={timezone} selected={user.timezone===timezone}>{timezone}</option>{/each}</select></Field><Field label={t('field.theme')}><select class="input" name="theme"><option value="system" selected={user.theme==='system'}>{t('theme.system')}</option>{#each boot.themes as theme}<option value={theme.name} selected={user.theme===theme.name}>{theme.displayName}</option>{/each}</select></Field><button class="button is-primary">{t('common.save')}</button></form><dl><dt>{t('field.email')}</dt><dd>{user.email}</dd><dt>{t('profile.user-id')}</dt><dd><code>{user.id}</code></dd><dt>{t('profile.created-at')}</dt><dd>{dateLabel(user.createdAt)}</dd><dt>{t('profile.last-login')}</dt><dd>{dateLabel(user.lastLoginAt)}</dd></dl></section>
 <section class="box"><h2 class="subtitle">{t('profile.accounts.title')}</h2>{#if p.personalAccount}<p><a href={`/accounts/${enc(p.personalAccount.id)}`}>{t('profile.account.personal')}</a> · {t('profile.role.owner')}{#if p.activeAccountId===p.personalAccount.id} · {t('profile.account.active')}{/if}</p>{/if}{#each list(p.accountMemberships) as account}<p><a href={`/accounts/${enc(account.id)}`}>{account.name}</a> · {t('profile.account.organization')} · {t(`profile.role.${account.role}`)}{#if p.activeAccountId===account.id} · {t('profile.account.active')}{/if}</p>{:else}<p>{t('profile.account.none')}</p>{/each}</section>
 <div class="settings-list"><Setting title={t('profile.password.title')} text={t('profile.password.text')} href="/profile/password"/><Setting title="TOTP" text={p.totpEnabled?t('status.active'):t('profile.totp.not-configured')} href="/profile/totp"/><Setting title={t('profile.passkeys.title')} text={tp('profile.passkeys.registered',p.webAuthnKeyCount??0)} href="/profile/webauthn"/><Setting title={t('profile.api-keys.title')} text={t('profile.api-keys.text')} href="/profile/api-keys"/></div>
</Page>
{:else if boot.page==='profile/password'}<Page title={t('profile.password.title')} error={p.error} success={p.success} narrow><section class="box"><form method="post"><input type="hidden" name="csrf_token" value={csrf}><Field label={t('profile.password.current')}><input class="input" type="password" name="current_password" required></Field><Field label={t('field.new-password')}><input class="input" type="password" name="new_password" oninput={strength} required><Strength value={score}/></Field><Field label={t('field.repeat')}><input class="input" type="password" name="new_password_confirm" required></Field><button class="button is-primary">{t('profile.password.change')}</button></form></section></Page>
{:else if boot.page==='profile/totp'}<Page title={t('auth.two-factor')} error={p.error} success={p.success} narrow><Notice kind="warning" text={t('profile.totp.notice')}/><section class="box"><span class:active={p.totpActive} class="status">{p.totpActive?t('status.active'):t('status.inactive')}</span>{#if p.provisioningUri}<p class="mt-4"><a class="button is-fullwidth" href={p.provisioningUri}>{t('profile.totp.open-authenticator')}</a></p><Field label={t('profile.totp.secret')}><input class="input" readonly value={p.secretFormatted}></Field>{/if}<form method="post"><input type="hidden" name="csrf_token" value={csrf}><input type="hidden" name="action" value={p.totpActive?'disable':'enable'}><Field label={t('profile.totp.current-code')}><input class="input code-input" name="code" inputmode="numeric" pattern={'[0-9]{6,8}'} required></Field><button class:is-danger={p.totpActive} class="button is-primary">{p.totpActive?t('common.disable'):t('common.enable')}</button></form></section></Page>
{:else if boot.page==='profile/webauthn'}<Page title={t('profile.passkeys.title')} error={p.error} success={p.success} narrow><section class="box"><div class="inline-form"><input class="input" bind:value={keyName} placeholder={t('profile.passkeys.name')}><button class:loading={busy} class="button is-primary" onclick={registerPasskey}>{t('profile.passkeys.register')}</button></div>{#if passkeyError}<Notice kind="danger" text={passkeyError}/>{/if}</section><DataTable rows={list(p.keys)} cols={['name','created_at','last_used_at']} labels={[t('field.name'),t('table.registered'),t('table.last-used')]} {csrf} action={(r)=>`/profile/webauthn/${r.credential_id_url}/delete`} actionText={t('common.remove')}/></Page>
{:else if boot.page==='profile/api_keys'}<Page title={t('profile.api-keys.title')} error={p.error} success={p.success} narrow>{#if p.newToken}<Notice kind="warning" text={t('profile.api-keys.copy-token',{token:p.newToken})}/>{/if}<section class="box"><form class="inline-form" method="post"><input type="hidden" name="csrf_token" value={csrf}><input class="input" name="name" placeholder={t('field.name')} required><button class="button is-primary">{t('common.create')}</button></form></section><DataTable rows={list(p.keys)} cols={['name','created_at','last_used']} labels={[t('field.name'),t('table.created'),t('table.last-used')]} {csrf} action={(r)=>`/profile/api-keys/${r.id}/revoke`} actionText={t('profile.api-keys.revoke')}/></Page>
{:else if boot.page==='zones/record_edit'}<Page title={t('page.record-edit.title')} error={p.error} narrow>{#if p.record}<section class="box"><form method="post" action={`/accounts/${enc(p.accountId)}/zones/${enc(p.managedZoneId)}/records/${enc(p.record.id)}/update`}><input type="hidden" name="csrf_token" value={csrf}><div class="form-grid"><Field label={t('field.name')}><input class="input" name="name" value={p.record.name} required></Field><Field label="TTL"><input class="input" name="ttl" type="number" value={p.record.ttl} required></Field><Field label={t('field.content')}><input class="input" name="content" value={p.record.content} required></Field></div><button class="button is-primary">{t('common.save')}</button></form></section>{/if}</Page>
{:else if boot.page==='zones/dnssec'}<Page title={`${t('page.dnssec.title')} · ${p.managedZoneId}`} error={p.error} success={p.success} narrow><section class="box"><p>{t('dnssec.status')}: <strong>{t(`dnssec.state.${p.profile?.state??'unknown'}`)}</strong></p><form class="buttons mt-4" method="post"><input type="hidden" name="csrf_token" value={csrf}><button class="button is-primary" name="action" value="enable">{t('common.enable')}</button><button class="button is-danger" name="action" value="disable">{t('common.disable')}</button></form></section></Page>
{:else if boot.page==='invitations/accept'}<Page title={t('accounts.invitation-title')} error={p.error} narrow><section class="box"><p>{t('accounts.invitation-for',{email:p.invitation?.email??''})}</p><p>{t(`profile.role.${p.invitation?.role??'viewer'}`)}</p><p>{t('accounts.invitation-expires',{date:p.invitation?.expiresAt??''})}</p><form class="buttons" method="post"><input type="hidden" name="csrf_token" value={csrf}><button class="button is-primary" name="action" value="accept">{t('accounts.invitation-accept')}</button><button class="button" name="action" value="decline">{t('accounts.invitation-decline')}</button></form></section></Page>
{:else if boot.page==='accounts/edit'}<Page title={p.account?.name??t('page.accounts.title')} error={p.error} success={p.success} narrow><div class="page-actions"><a class="button" href="/accounts">← {t('navigation.accounts')}</a>{#if p.account?.type!=='personal'}<a class="button" href={`/accounts/${enc(p.account.id)}/members`}>{t('accounts.members')}</a>{/if}</div>{#if p.account}<section class="box"><h2 class="subtitle">{p.account.type==='personal'?t('profile.account.personal'):t('account.organization-details')}</h2><p class="status">{p.account.isActive?t('account.status.active'):t('account.status.inactive')}</p>{#if p.account.type==='personal'}<p>{t('account.personal-managed-profile')}</p>{:else}<form method="post"><input type="hidden" name="csrf_token" value={csrf}><Field label={t('field.name')}><input class="input" name="name" value={p.account.name} maxlength="255" required></Field><Field label={t('account.customer-number')}><input class="input" name="customer_number" value={p.account.customerNumber??''} maxlength="64"></Field><Field label={t('account.external-reference')}><input class="input" name="external_reference" value={p.account.externalReference??''} maxlength="255"></Field><button class="button is-primary">{t('common.save')}</button></form>{/if}</section>{#if p.usage}<section class="box"><h2 class="subtitle">{t('account.resources.title')}</h2><p>{t('account.resources.zones')}: {p.usage.usedZones} / {p.usage.maxZones===null?t('account.resources.unlimited'):p.usage.maxZones}</p><p>{t('account.resources.members')}: {p.usage.usedMembers} / {p.usage.maxMembers===null?t('account.resources.unlimited'):p.usage.maxMembers}</p><p>{t('account.resources.providers')}: {p.usage.usedProviderAccounts} / {p.usage.maxProviderAccounts===null?t('account.resources.unlimited'):p.usage.maxProviderAccounts}</p>{#if p.account.type!=='personal'}<form class="form-grid mt-4" method="post"><input type="hidden" name="csrf_token" value={csrf}><input type="hidden" name="action" value="limits"><Field label={t('account.resources.max-zones')}><input class="input" type="number" min="0" name="max_zones" value={p.usage.maxZones??''}></Field><Field label={t('account.resources.max-members')}><input class="input" type="number" min="0" name="max_members" value={p.usage.maxMembers??''}></Field><Field label={t('account.resources.max-providers')}><input class="input" type="number" min="0" name="max_provider_accounts" value={p.usage.maxProviderAccounts??''}></Field><button class="button">{t('account.resources.save-limits')}</button></form>{/if}</section>{/if}{#if p.account.type!=='personal'}<section class="box"><form class="buttons" method="post"><input type="hidden" name="csrf_token" value={csrf}>{#if p.account.isActive}<button class="button" name="action" value="deactivate" onclick={(e)=>ask(e,t('account.confirm-deactivate'))}>{t('account.deactivate')}</button>{:else}<button class="button is-primary" name="action" value="activate" onclick={(e)=>ask(e,t('account.confirm-activate'))}>{t('account.activate')}</button>{/if}<button class="button is-danger" name="action" value="delete" onclick={(e)=>ask(e,t('account.confirm-delete'))}>{t('account.delete')}</button></form></section>{/if}{/if}</Page>
{:else if boot.page==='accounts/members'}<Page title={t('accounts.members')} error={p.error} success={p.success}><div class="page-actions"><a class="button" href={`/accounts/${enc(p.account?.id)}`}>← {p.account?.name??t('navigation.accounts')}</a></div>{#if p.account}<section class="box"><h2 class="subtitle">{p.account.name}</h2><form class="form-grid" method="post"><input type="hidden" name="csrf_token" value={csrf}><input type="hidden" name="action" value="invite"><Field label={t('field.email')}><input class="input" type="email" name="email" placeholder={t('accounts.invitation-email-placeholder')} required></Field><Field label={t('field.role')}><select class="input" name="role">{#each list(p.roles).filter(role=>role.value!=='owner') as role}<option value={role.value}>{t(`profile.role.${role.value}`)}</option>{/each}</select></Field><button class="button is-primary">{t('accounts.member-add')}</button></form><form class="form-grid mt-4" method="post" action={`/accounts/${enc(p.account.id)}/ownership`} onsubmit={(e)=>ask(e,t('account.confirm-ownership-transfer'))}><input type="hidden" name="csrf_token" value={csrf}><Field label={t('account.new-owner')}><input class="input" name="user_id" placeholder={t('accounts.user-id-placeholder')} required></Field><button class="button">{t('account.transfer-ownership')}</button></form></section>{#if list(p.invitations).length}<section class="box"><h2 class="subtitle">{t('accounts.invitations')}</h2>{#each list(p.invitations) as invitation}<article class="resource-card"><div><strong>{invitation.email}</strong><span class="status">{t(`account.invitation.status.${invitation.status}`)} · {t(`profile.role.${invitation.role}`)}</span><small>{invitation.expiresAt}</small></div>{#if invitation.status==='pending'}<form method="post"><input type="hidden" name="csrf_token" value={csrf}><input type="hidden" name="action" value="revoke_invitation"><input type="hidden" name="invitation_id" value={invitation.id}><button class="button is-small is-danger">{t('accounts.invitation-revoke')}</button></form>{/if}</article>{/each}</section>{/if}<div class="resource-grid">{#each list(p.members) as member}<article class="resource-card"><div><strong>{member.displayName??member.email}</strong><small>{member.email}</small></div><div class="buttons">{#if member.role==='owner'}<span class="status">{t('profile.role.owner')}</span>{:else}<form method="post"><input type="hidden" name="csrf_token" value={csrf}><input type="hidden" name="action" value="role"><input type="hidden" name="user_id" value={member.userId}><select class="input" name="role" onchange={(e)=>{const f=(e.currentTarget as HTMLSelectElement).form;if(f)f.submit()}}>{#each list(p.roles).filter(role=>role.value!=='owner') as role}<option value={role.value} selected={member.role===role.value}>{t(`profile.role.${role.value}`)}</option>{/each}</select></form><form method="post" onsubmit={(e)=>ask(e,t('account.confirm-member-remove'))}><input type="hidden" name="csrf_token" value={csrf}><input type="hidden" name="action" value="remove"><input type="hidden" name="user_id" value={member.userId}><button class="button is-small is-danger">{t('common.remove')}</button></form>{/if}</div></article>{/each}</div>{/if}</Page>
{:else if boot.page==='accounts/list'}<Page title={t('page.accounts.title')} error={p.error}><section class="box"><form class="form-grid" method="post"><input type="hidden" name="csrf_token" value={csrf}><Field label={t('field.name')}><input class="input" name="name" required></Field><Field label={t('field.slug')}><input class="input" name="slug" pattern={'[a-z0-9-]{2,64}'} required></Field><button class="button is-primary">{t('accounts.create')}</button></form></section><section class="box"><form class="form-grid" method="get" action="/accounts"><Field label={t('accounts.search')}><input class="input" name="q" value={p.search??''}></Field><Field label={t('accounts.type-filter')}><select class="input" name="type"><option value="all" selected={p.type==='all'}>{t('common.all')}</option><option value="personal" selected={p.type==='personal'}>{t('profile.account.personal')}</option><option value="organization" selected={p.type==='organization'}>{t('profile.account.organization')}</option></select></Field><Field label={t('accounts.status-filter')}><select class="input" name="status"><option value="all" selected={p.status==='all'}>{t('common.all')}</option><option value="active" selected={p.status==='active'}>{t('account.status.active')}</option><option value="inactive" selected={p.status==='inactive'}>{t('account.status.inactive')}</option></select></Field><Field label={t('accounts.role-filter')}><select class="input" name="role"><option value="all" selected={p.role==='all'}>{t('common.all')}</option>{#each list(p.roles) as role}<option value={role.value} selected={p.role===role.value}>{t(`profile.role.${role.value}`)}</option>{/each}</select></Field><button class="button">{t('common.search')}</button></form></section><div class="resource-grid">{#each list(p.accounts) as account}<article class="resource-card"><div><a class="resource-title" href={`/accounts/${account.id}`}>{account.kind==='personal'?t('profile.account.personal'):account.name}</a><span class="status">{t(`profile.account.${account.kind}`)} · {account.isActive?t('account.status.active'):t('account.status.inactive')}</span></div><div class="buttons"><form method="post" action="/accounts/active"><input type="hidden" name="csrf_token" value={csrf}><input type="hidden" name="account_id" value={account.id}><button class="button is-small" disabled={p.activeAccountId===account.id}>{p.activeAccountId===account.id?t('account.selected'):t('account.select')}</button></form><a class="button is-small" href={`/accounts/${account.id}`}>{t('common.edit')}</a>{#if account.kind!=='personal'}<a class="button is-small" href={`/accounts/${account.id}/members`}>{t('accounts.members')}</a>{#if account.isActive}<a class="button is-small" href={`/accounts/${account.id}/providers`}>{t('navigation.providers')}</a>{/if}{/if}</div></article>{:else}<p class="empty">{t('accounts.empty')}</p>{/each}</div><div class="page-actions">{#if p.page>1}<a class="button" href={`/accounts?q=${enc(p.search)}&type=${enc(p.type)}&role=${enc(p.role)}&status=${enc(p.status)}&page=${p.page-1}`}>{t('accounts.previous-page')}</a>{/if}{#if p.hasNext}<a class="button" href={`/accounts?q=${enc(p.search)}&type=${enc(p.type)}&role=${enc(p.role)}&status=${enc(p.status)}&page=${p.page+1}`}>{t('accounts.next-page')}</a>{/if}</div></Page>
{:else if boot.page==='iam/user_edit'}<Page title={p.target?.displayName??p.target?.email??t('page.users.title')} error={p.error} success={p.success} narrow>{#if p.target}<div class="page-actions"><a class="button" href="/users">← {t('navigation.users')}</a></div><section class="box"><dl><dt>{t('field.email')}</dt><dd>{p.target.email}</dd><dt>{t('profile.user-id')}</dt><dd><code>{p.target.id}</code></dd></dl><form method="post"><input type="hidden" name="csrf_token" value={csrf}><input type="hidden" name="action" value="display_name"><Field label={t('field.display-name')}><input class="input" name="display_name" value={p.target.displayName??''} maxlength="64"></Field><button class="button is-primary">{t('common.save')}</button></form><form method="post" class="mt-4"><input type="hidden" name="csrf_token" value={csrf}><input type="hidden" name="action" value="status"><input type="hidden" name="active" value={p.target.active?'0':'1'}><button class="button" class:is-danger={p.target.active}>{p.target.active?t('users.status.inactive'):t('users.status.active')}</button></form><form method="post" action={`/users/${enc(p.target.id)}/delete`} class="mt-4" onsubmit={(e)=>ask(e,t('users.confirm-delete'))}><input type="hidden" name="csrf_token" value={csrf}><button class="button is-danger">{t('common.delete')}</button></form></section><section class="box"><h2 class="subtitle">{t('users.roles')}</h2><form method="post"><input type="hidden" name="csrf_token" value={csrf}><div class="form-grid">{#each list<Data>(p.allRoles) as role}<label class="checkbox"><input type="checkbox" name="roles[]" value={role.id} checked={list<Data>(p.target.roles).some(r=>r.id===role.id)}> {role.name}</label>{/each}</div><button class="button is-primary">{t('common.save')}</button></form></section>{/if}</Page>
{:else if boot.page==='iam/users'}<Page title={t('page.users.title')} error={p.error} success={p.success}><section class="box"><form class="form-grid" method="get" action="/users"><Field label={t('users.search')}><input class="input" name="q" value={p.search??''}></Field><Field label={t('users.status-filter')}><select class="input" name="status"><option value="active" selected={p.status==='active'}>{t('users.status.active')}</option><option value="inactive" selected={p.status==='inactive'}>{t('users.status.inactive')}</option><option value="all" selected={p.status==='all'}>{t('common.all')}</option></select></Field><Field label={t('users.account-filter')}><input class="input" name="account" value={p.account??''}></Field><Field label={t('users.membership-role-filter')}><select class="input" name="membership_role"><option value="all" selected={p.membershipRole==='all'}>{t('common.all')}</option>{#each list(p.membershipRoles) as role}<option value={role.value} selected={p.membershipRole===role.value}>{t(`profile.role.${role.value}`)}</option>{/each}</select></Field><button class="button">{t('common.search')}</button></form></section><section class="box"><form class="form-grid" method="post" action="/users"><input type="hidden" name="csrf_token" value={csrf}><Field label={t('field.email')}><input class="input" type="email" name="email" required></Field><Field label={t('field.password')}><input class="input" type="password" name="password" oninput={strength} required><Strength value={score}/></Field><button class="button is-primary">{t('users.create')}</button></form></section><div class="resource-grid">{#each list(p.users) as target}<article class="resource-card"><div><a class="resource-title" href={`/users/${enc(target.id)}`}>{target.displayName??target.email}</a><span class="status">{target.active?t('users.status.active'):t('users.status.inactive')}</span><small>{target.email}</small></div></article>{:else}<p class="empty">{t('users.empty')}</p>{/each}</div><div class="page-actions">{#if p.page>1}<a class="button" href={`/users?q=${enc(p.search)}&status=${enc(p.status)}&account=${enc(p.account)}&membership_role=${enc(p.membershipRole)}&page=${p.page-1}`}>{t('users.previous-page')}</a>{/if}{#if p.hasNext}<a class="button" href={`/users?q=${enc(p.search)}&status=${enc(p.status)}&account=${enc(p.account)}&membership_role=${enc(p.membershipRole)}&page=${p.page+1}`}>{t('users.next-page')}</a>{/if}</div></Page>
{:else if boot.page==='iam/roles'}<Page title={t('page.roles.title')} error={p.error} success={p.success}><section class="box"><form method="post" action="/roles"><input type="hidden" name="csrf_token" value={csrf}><Field label={t('field.name')}><input class="input" name="name" required></Field>{#each actionGroups as group}<fieldset class="permission-group"><legend>{actionGroupLabel(group)}</legend>{#if group.description}<p class="muted">{t(group.description)}</p>{/if}<div class="form-grid">{#each group.permissionIds as permissionId}<label class="checkbox"><input type="checkbox" name="permissions[]" value={permissionId}> {permissionLabel(permissionId)}</label>{/each}</div></fieldset>{/each}{#if ungroupedPermissions.length}<fieldset class="permission-group"><legend>{t('roles.individual-permissions')}</legend><div class="form-grid">{#each ungroupedPermissions as permission}<label class="checkbox"><input type="checkbox" name="permissions[]" value={permission.id}> {t(permission.label)}</label>{/each}</div></fieldset>{/if}<button class="button is-primary mt-4">{t('roles.create')}</button></form></section><section class="box"><h2 class="subtitle">{t('roles.existing')}</h2><div class="resource-grid">{#each list(p.roles) as role}<article class="resource-card"><div><a class="resource-title" href={`/roles/${enc(role.id)}`}>{role.name}</a><span class="status">{role.isBuiltIn?t('roles.built-in'):t('roles.custom')}</span></div></article>{:else}<p class="empty">{t('roles.empty')}</p>{/each}</div></section></Page>
{:else if boot.page==='iam/role_edit'}<Page title={p.role?.name??t('page.role-edit.title')} error={p.error} success={p.success} narrow><div class="page-actions"><a class="button" href="/roles">← {t('page.roles.title')}</a></div>{#if p.role}<section class="box"><form method="post"><input type="hidden" name="csrf_token" value={csrf}><Field label={t('field.name')}><input class="input" name="name" value={p.role.name} readonly={p.role.isBuiltIn} required></Field>{#each actionGroups as group}<fieldset class="permission-group" disabled={p.role.isBuiltIn}><legend>{actionGroupLabel(group)}</legend>{#if group.description}<p class="muted">{t(group.description)}</p>{/if}<div class="form-grid">{#each group.permissionIds as permissionId}<label class="checkbox"><input type="checkbox" name="permissions[]" value={permissionId} checked={list<string>(p.role.permissions).includes(permissionId)}> {permissionLabel(permissionId)}</label>{/each}</div></fieldset>{/each}{#if ungroupedPermissions.length}<fieldset class="permission-group" disabled={p.role.isBuiltIn}><legend>{t('roles.individual-permissions')}</legend><div class="form-grid">{#each ungroupedPermissions as permission}<label class="checkbox"><input type="checkbox" name="permissions[]" value={permission.id} checked={list<string>(p.role.permissions).includes(permission.id)}> {t(permission.label)}</label>{/each}</div></fieldset>{/if}{#if p.role.isBuiltIn}<Notice kind="info" text={t('roles.built-in-read-only')}/>{:else}<button class="button is-primary">{t('common.save')}</button>{/if}</form></section>{/if}</Page>
{:else if boot.page==='credentials'}<Page title={t('page.credentials.title')} error={p.error} success={p.success}>{#each providerDefinitions(p.providerDefinitions) as [providerId,provider]}<section class="box"><h2 class="subtitle">{provider.label} {p.configured?.[providerId]?`· ${t('status.configured')}`:''}</h2><form method="post"><input type="hidden" name="csrf_token" value={csrf}><input type="hidden" name="provider" value={providerId}><div class="form-grid">{#each credentialFields(provider) as field}<Field label={field.label}>{#if field.type==='checkbox'}<input class="checkbox" type="checkbox" name={field.input} value="1" checked={p.values?.[field.input]==='1'}>{:else}<input class="input" type={field.secret?'password':'text'} name={field.input} value={p.values?.[field.input]??field.default??''} required={field.required}>{/if}</Field>{/each}</div><button class="button is-primary">{t('common.save')}</button></form></section>{/each}</Page>
{:else if boot.page==='settings'}<Page title={t('page.settings.title')} error={p.error} success={p.success} narrow><form method="post"><input type="hidden" name="csrf_token" value={csrf}><section class="box"><Field label={t('settings.application-name')}><input class="input" name="app_name" value={p.fields?.app_name}></Field><Field label={t('settings.hostname')}><input class="input" name="app_hostname" value={p.fields?.app_hostname}></Field><Field label={t('field.theme')}><select class="input" name="theme_name">{#each boot.themes as theme}<option value={theme.name} selected={theme.name===p.fields?.theme_name}>{theme.displayName}</option>{/each}</select></Field><label class="checkbox"><input type="checkbox" name="app_force_https" value="1" checked={p.fields?.app_force_https}> {t('settings.force-https')}</label><label class="checkbox"><input type="checkbox" name="app_debug" value="1" checked={p.fields?.app_debug}> {t('settings.debug')}</label></section><section class="box form-grid"><Field label={t('settings.password-min-length')}><input class="input" type="number" name="pwd_min_length" value={p.fields?.pwd_min_length}></Field><Field label={t('settings.password-min-score')}><input class="input" type="number" name="pwd_min_score" value={p.fields?.pwd_min_score}></Field><Field label={t('settings.mailer-dsn')}><input class="input" name="mailer_dsn" value={p.fields?.mailer_dsn}></Field><Field label={t('settings.sender')}><input class="input" type="email" name="mailer_from_address" value={p.fields?.mailer_from_address}></Field></section><button class="button is-primary">{t('common.save')}</button></form></Page>
{:else}<Page title={boot.page.split('/').slice(-1)[0]?.replace(/_/g,' ')??'TowerDNS'} error={p.error} success={p.success}><AdminPage page={boot.page} data={p} {csrf}/></Page>{/if}
</main>
